* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  // font-family: samim;
}

.mb-5 {
  margin-bottom: 5vw;
}

.mt-3 {
  margin-top: 3vw !important;
}

@for $i from 1 through 200 {
  .width-#{$i} {
    width: #{$i}vw;
  }
}

@for $i from 1 through 200 {
  .width-#{$i}f {
    width: $i * 1% !important;
  }
}

@for $i from 1 through 200 {
  .height-#{$i} {
    height: #{$i}vw;
  }
}

@for $i from 1 through 200 {
  .height-#{$i}f {
    height: $i * 1% !important;
  }
}

@for $i from 1 through 200 {
  .marin-#{$i}-t {
    margin-top: #{$i}vw;
  }
}

@for $i from 1 through 200 {
  .marin-#{$i}-b {
    margin-bottom: #{$i}vw;
  }
}

@for $i from 1 through 200 {
  .padding#{$i} {
    padding: #{$i}vw;
  }
}

@for $i from 1 through 200 {
  .padding-#{$i}-f {
    padding: $i * 1% !important;
  }
}

.frist-table {
  width: 63% !important;
  height: 20% !important;
}

.third-table {
  width: 75% !important;
  height: 25% !important;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100vh;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: cover;
  position: relative;

  // font-family: samim;
  #spaceTemplate {
    display: flex;
    justify-content: center;
    align-items: center;

    background-image: url(data:image/png;base64,);
    background-repeat: no-repeat;
    background-position: center center;
    background-size: cover;
    position: relative;
    background-color: #55bec2;

    .loader {
      background-color: #fff;
      background-image: url('data:image/gif;base64,');
      width: 100%;
      height: 100%;
      background-position: center;
      background-repeat: no-repeat;
      background-size: 50%;
      position: absolute;
      z-index: 10;
      top: 0;
      right: 0;
    }

    .transition {
      position: fixed;
      top: 0;
      left: 0;
      top: 50% !important;
      transform: translateY(-50%) !important;
      width: 100%;
      height: 100%;
      z-index: 0;
      overflow: hidden;
      display: flex;
      justify-content: center;
      align-items: center;

      &.active {
        z-index: 1000;

        #transition {
          pointer-events: auto;
          width: 100%;
          transform: scale(1.5);
          z-index: 10000;
        }
      }
    }

    .frist-table {
      width: 30%;
      height: 22vw;
    }

    .logo {
      background-image: url('../images/logo.png');
      background-repeat: no-repeat;
      background-position: top right;
      background-size: 100%100%;
      width: 6vw;
      height: 6vw;
      right: 6%;
      top: 1%;
      position: absolute;
      z-index: 999999;
    }

    &.main {
      .start-button {
        height: 17vw;
        width: 17vw;
        background-position: center;
        background-repeat: no-repeat;
        background-size: 100% 100%;
        position: relative;
        z-index: 9999;
        background-image: url('data:image/png;base64,');
        animation: zoom 30s infinite;
        -webkit-animation: zoom 2.5s infinite ease-in-out;
        cursor: pointer;
        background-color: transparent;
        border: 0;
      }

      .isSuccess {
        width: 100%;
        height: 100%;
        display: flex;
        justify-content: center;
        align-items: center;

        &.isEng {
          p {
            // letter-spacing: 0.02vw !important;
          }

          .feedback-description {
            direction: ltr !important;
          }
        }
      }

      @-webkit-keyframes zoom {
        0% {
          -webkit-transform: scale(0.8) rotate(-10deg);
          transform: scale(0.8) rotate(-10deg);
        }

        50% {
          -webkit-transform: scale(1) rotate(10deg);
          transform: scale(1) rotate(10deg);
        }

        100% {
          -webkit-transform: scale(0.8) rotate(-10deg);
          transform: scale(0.8) rotate(-10deg);
        }
      }

      @keyframes zoom {
        0% {
          -webkit-transform: scale(0.8) rotate(-10deg);
          transform: scale(0.8) rotate(-10deg);
        }

        50% {
          -webkit-transform: scale(1) rotate(10deg);
          transform: scale(1) rotate(10deg);
        }

        100% {
          -webkit-transform: scale(0.8) rotate(-10deg);
          transform: scale(0.8) rotate(-10deg);
        }
      }

      .sectionSpace {
        width: 100%;
        height: 100%;
        overflow: hidden;

        .music {
          position: absolute;
          width: 5vw;
          height: 5vw;
          background-size: 100%;
          background-repeat: no-repeat;
          top: 1%;
          left: 1%;
          z-index: 999;

          user-select: none;

          &.play {
            background-image: url('data:image/png;base64,');
          }

          &.mute {
            background-image: url('data:image/png;base64,');
          }
        }

        /* Styles for popup */
        .popup {
          display: none;

          position: absolute;
          z-index: 1000;
          width: 35vw;
          height: 35vw;

          background-size: 100% 100%;
          background-repeat: no-repeat;
          background-position: center;
          left: 50%;
          top: 50%;
          transform: translate(-50%, -50%);
          padding: 2vw;
          animation: fadeIn 0.3s ease-out forwards;
          background-image: url('data:image/png;base64,');
        }

        .popup-content {
          position: relative;
          display: flex;
          justify-content: center;
          align-items: center;
          height: 100%;
          padding-top: 5vw;

          p {
            color: white !important;
            font-size: 4vw;
          }
        }

        .popup-content .close {
          position: absolute;
          top: -2vw;
          right: 0vw;

          color: #aaa;
          font-size: 24px;
          font-weight: bold;
          cursor: pointer;
          position: absolute;
          width: 5vw;
          height: 5vw;
          background-size: 100%;
          background-repeat: no-repeat;

          background-image: url('data:image/png;base64,');
        }

        .overlay {
          display: none;
          position: absolute;
          z-index: 999;

          left: 0;
          top: 0;
          width: 100%;
          height: 100%;
          background-color: rgba(0, 0, 0, 0.5);

          animation: fadeInOverlay 0.3s ease-out forwards;
        }

        @keyframes fadeIn {
          from {
            opacity: 0;
          }

          to {
            opacity: 1;
          }
        }

        @keyframes fadeInOverlay {
          from {
            opacity: 0;
          }

          to {
            opacity: 1;
          }
        }

        .popup-open {
          pointer-events: none;
        }

        .popup-closed {
          pointer-events: auto;
        }

        .information {
          position: absolute;
          width: 5vw;
          height: 5vw;
          background-size: 100%;
          background-repeat: no-repeat;
          top: 13%;
          left: 1%;
          z-index: 999;
          background-image: url('data:image/png;base64,');

          &.disable {
            pointer-events: none;
          }

          &.none {
            pointer-events: none;
          }
        }

        &.display {
          .screen-question {
            animation: fadeInOverlay 0.3s ease-out forwards;
          }
        }

        .screen-question {
          opacity: 0;
          width: 100%;
          height: 100%;
          display: flex;
          justify-content: center;
          align-items: flex-end;

          .sub-table,
          .body_table {
            background-repeat: no-repeat;
            background-size: 100% 100%;
            display: -webkit-box;
            display: -ms-flexbox;
            display: flex;
            -webkit-box-pack: center;
            -ms-flex-pack: center;
            justify-content: center;
            -webkit-box-align: center;
            -ms-flex-align: center;
            align-items: center;
            background-image: url(data:image/png;base64,);
            -webkit-box-orient: vertical;
            -webkit-box-direction: normal;
            -ms-flex-direction: column;
            flex-direction: column;
            position: relative;
            padding: 0.8vw;
            z-index: 10;

            &.main-table {
              margin-top: 3vw;

              .question {
                border-radius: 5vw;
              }

              .space_man {
                background-image: url(data:image/png;base64,);
                background-repeat: no-repeat;
                background-size: 100% 100%;
                -webkit-transform: scaleX(-1);
                transform: scaleX(-1);
                display: -webkit-box;
                display: -ms-flexbox;
                display: flex;
                -webkit-box-pack: center;
                -ms-flex-pack: center;
                justify-content: center;
                -webkit-box-align: center;
                -ms-flex-align: center;
                align-items: center;
                width: 6vw;
                height: 9vw;
                position: absolute;
                top: -10vw;
                -webkit-animation: spacemove 4s infinite;
                animation: spacemove 4s infinite;
                right: -2vw;
              }
            }

            &.sub-table {
              .question {
                border-radius: 8vh 10vh 8vh 5vh;
              }
            }
          }

          @-webkit-keyframes spacemove {
            0% {
              -webkit-transform: translateY(1.5vw) rotateY(0deg);
              transform: translateY(1.5vw) rotateY(0deg);
              -webkit-transform: translateX(1.5vw) rotateY(0deg);
              transform: translateX(1.5vw) rotateY(0deg);
            }

            50% {
              -webkit-transform: translateY(3vw) rotateY(5deg);
              transform: translateY(3vw) rotateY(5deg);
            }

            100% {
              -webkit-transform: translateY(1.5vw) rotateY(0deg);
              transform: translateY(1.5vw) rotateY(0deg);
              -webkit-transform: translateX(1.5vw) rotateY(0deg);
              transform: translateX(1.5vw) rotateY(0deg);
            }
          }

          @keyframes spacemove {
            0% {
              -webkit-transform: translateY(1.5vw) rotateY(0deg);
              transform: translateY(1.5vw) rotateY(0deg);
              -webkit-transform: translateX(1.5vw) rotateY(0deg);
              transform: translateX(1.5vw) rotateY(0deg);
            }

            50% {
              -webkit-transform: translateY(3vw) rotateY(5deg);
              transform: translateY(3vw) rotateY(5deg);
            }

            100% {
              -webkit-transform: translateY(1.5vw) rotateY(0deg);
              transform: translateY(1.5vw) rotateY(0deg);
              -webkit-transform: translateX(1.5vw) rotateY(0deg);
              transform: translateX(1.5vw) rotateY(0deg);
            }
          }

          .sub-table {
            background-image: url(data:image/png;base64,);
          }

          .screen {
            width: 100%;
            height: 100%;
            position: relative;
            margin: 0 auto 0.5%;
            background-image: url('');
            background-repeat: no-repeat;
            // pointer-events: none;
            background-position: bottom;
            background-size: 100% 100%;
            z-index: 2;
            display: flex;
            align-items: flex-end;
            justify-content: center;

            .hand {
              position: relative;
              width: 1vw;
              height: 1vw;
              display: none;

              &.display {
                display: block;
              }

              &.hide {
                display: none !important;
              }

              &::before {
                content: '';
                width: 5vw;
                height: 6vw;
                bottom: -2vw;
                left: -4vw;
                position: absolute;
                animation: submit 0.5s linear 0.2s infinite alternate;
                background-image: url(data:image/png;base64,);
                background-position: center;
                background-repeat: no-repeat;
                background-size: 100% 100%;
                transform: rotate(135deg);
              }

              &.help {
                width: 0;
                height: 0;
                bottom: -2vw;
                left: 0;

                &:before {
                  bottom: -9vw;
                  left: 10vw;
                  transform: rotate(332deg);
                  animation: changeposition 0.5s linear 0.2s infinite alternate;
                }
              }

              &.display-answer {
                &::before {
                  animation: displayAnswer 0.5s linear 0.2s infinite alternate;
                  bottom: -2vw;
                  left: 5vw;
                  transform: rotate(-114deg);
                }
              }
            }

            .finished {
              width: 100%;
              height: 100%;
              display: flex;
              position: absolute;
              top: 0;
              left: 0;
              right: 0;
              bottom: 0;
              justify-content: center;
              align-items: center;

              #robots {
                width: 100%;
                height: 100%;
              }
            }

            .check-button,
            .display-answer-button,
            .next-button,
            .levels {
              position: absolute;
              left: 5vw;
              top: -7vw;
              background-image: url('data:image/png;base64,');
              background-size: contain;
              background-repeat: no-repeat;
              z-index: 100000;
              width: 6vw;
              height: 7vw;
              // cursor: pointer;
              pointer-events: auto;

              &.disable {
                pointer-events: none;
              }
            }

            .check-button {
              pointer-events: none;

              &:not(.disable)::after {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 66%;
                pointer-events: auto;
              }

              .levels {
                left: 75%;
                top: 30%;
                height: 7vw;
                width: 7vw;
                pointer-events: none;

                &.disable {
                  pointer-events: none;
                }

                p {
                  height: inherit;
                  width: inherit;
                  color: wheat !important;
                  font-size: 3vw !important;
                  display: flex;
                  align-items: center;
                  justify-content: center;
                  pointer-events: none;
                }
              }

              &.disable {
                background-image: url('data:image/png;base64,');
              }
            }

            .display-answer-button {
              background-image: url('data:image/png;base64,');
              left: 17vw;
              top: -7vw;
              pointer-events: none;

              &:not(.disable)::after {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 66%;
                pointer-events: auto;
              }

              &.disable {
                background-image: url('data:image/png;base64,');
              }
            }

            .next-button {
              background-image: url('data:image/png;base64,');
              right: -1.5%;
              left: unset;
              top: 85%;
              width: 9vh;
              height: 9vh;
              z-index: 9999;

              &.disable {
                background-image: url('../images/disable-next.png');
              }

              &.hide {
                display: none;
              }

              .next {
                &::before {
                  animation: next 0.5s linear 0.2s infinite alternate;
                  bottom: 1vw;
                  left: -3vw;
                  transform: rotate(142deg);
                }
              }
            }

            .container-space {
              display: none;
              // width: 115vw;
              // height: 50vw;
              width: 95%;
              height: 95%;
              justify-content: space-around;

              &.active {
                opacity: 1;
                display: flex;
                pointer-events: auto;
                justify-self: center;
                align-items: center;
                flex-direction: column;
                justify-content: space-between;

                .question {
                  opacity: 1;
                  display: flex;
                  pointer-events: auto;
                  justify-self: center;
                  align-items: center;
                  flex-direction: column;
                }
              }

              .question {
                display: flex;

                justify-content: center;

                align-items: center;

                background-image: url(data:image/png;base64,);
                background-color: #680070;
                background-repeat: no-repeat;
                background-size: 100% 100%;

                width: 100%;
                height: 100%;

                display: none;
                justify-content: center;
                position: relative;
                top: 0;
                right: 0;
                left: 0;
                bottom: 0;
                direction: rtl;

                .break {
                  flex-basis: 100%;
                  height: 0;
                }

                label {
                  position: absolute;
                  top: -6vw;
                  right: 0;
                }

                .content {
                  width: 100%;
                  height: 100%;
                  display: inline-flex;
                  justify-content: center;
                  align-items: center;
                  flex-wrap: wrap;
                  align-content: space-evenly;
                  // direction: ltr;

                  p {
                    direction: ltr;
                    display: flex;
                    flex-wrap: wrap;
                    font-size: 3vw;
                    // font-family: samim;
                    color: white !important;
                    font-weight: bold;

                    &.text {
                      direction: rtl;
                      // font-family: samim;
                      font-weight: bold;
                      color: white !important;
                    }

                    &.number {
                      // font-family: ArialRounded;
                      color: white !important;
                    }

                    &.f-size {
                      font-size: 9vw;
                    }
                  }

                  .fraction {
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    flex-direction: column;
                    background-color: transparent !important;
                    margin-left: 0.5vw;
                    margin-right: 0.5vw;
                    width: auto;
                    position: relative;

                    .line {
                      border-bottom: 0.2vw solid white;
                      width: 7vh;
                      margin: 0.5vw 0;
                    }

                    .up,
                    .down {
                      text-align: center;
                      display: flex;
                      height: 6vw;

                      p,
                      .ans {
                        margin: 0.5vw 1vw 1vw 0.5vw !important;
                        padding: 0 1.5vw;
                        display: flex;
                        align-items: center;
                        font-size: 3vw;
                      }
                    }

                    .up {
                      p,
                      .ans {
                        margin-top: 2vw !important;
                      }
                    }
                  }
                }

                @keyframes fadeIn {
                  0% {
                    opacity: 0;
                  }

                  100% {
                    opacity: 1;
                  }
                }

                @keyframes fadeout {
                  0% {
                    opacity: 1;
                  }

                  100% {
                    opacity: 0;
                  }
                }

                .chooses {
                  display: flex;
                  width: 100%;
                  justify-content: space-evenly;
                  animation: fadeIn 4s;
                  margin-top: 1vw;

                  .choose {
                    width: 29vh;
                    height: 9vw;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    background-size: 100% 100%;
                    background-position: center;
                    background-repeat: no-repeat;
                    background-image: url('data:image/png;base64,');
                    pointer-events: auto;

                    p {
                      pointer-events: none;
                      font-size: 2.5vw;
                      // font-family: ArialRounded;
                    }

                    &.true {
                      background-image: url('data:image/png;base64,');
                    }

                    &.false {
                      background-image: url('data:image/png;base64,');
                      pointer-events: none;
                    }
                  }
                }
              }
            }
          }
        }

        input {
          font-size: 2vw;
          width: 8vw;
          height: 5vw;
          outline: none;
          margin: 0 0.5vw;
          padding: 0;
          color: white;
          letter-spacing: 0.2vw;
          text-align: center;
          // font-family        : ArialRounded;
          font-weight: bold;
          background-image: url('data:image/png;base64,');
          background-repeat: no-repeat;
          background-position: center;
          background-size: 105%105%;
          border: 0;
          background-color: transparent;
          // font-family        : ArialRounded;
          caret-color: black;

          &.right {
            background-image: url('data:image/png;base64,');
            pointer-events: none;
          }

          &.false {
            background-image: url('data:image/png;base64,');
            pointer-events: none;
          }

          &.showAnswer {
            background-image: url('data:image/png;base64,');
            pointer-events: none;
          }

          &.displayinput {
            background-image: url('data:image/png;base64,');
            pointer-events: none;
          }
        }

        .table {
          input {
            font-size: 2vw;
            width: 100%;
            // height: 4vw;
            // width: 15vh;
            height: 100%;
            outline: none;
            // margin: 0 0.5vw;
            padding: 0;
            color: white;
            letter-spacing: 0.5vw;
            text-align: center;
            // font-family: ArialRounded;
            font-weight: bold;

            background-repeat: no-repeat;
            background-position: center;
            background-size: 100%100%;
            border: 0;
            background-color: transparent;
            caret-color: black;

            // font-family: ArialRounded;
            &.right {
              background-color: #41f97f;
              color: #fff;
              pointer-events: none;
            }

            &.false {
              background-color: #f789a1;
              color: #fff;
            }

            &.inactive {
              pointer-events: none;
              background-color: green;
            }

            &.showAnswer {
              background-color: #ffa162;
              color: #fff;
              pointer-events: none;
            }

            &.displayinput {
              background-color: #ffa162;
              color: #fff;
              pointer-events: none;
            }
          }
        }

        .roundOne {
          transition: 2s;
          opacity: 0;
          z-index: 0;
          display: contents;

          &.activeRound {
            width: 100%;
            transition: 2s;
            position: unset !important;
            opacity: 1;
          }
        }

        .round {
          width: 100%;
          display: flex;
          justify-content: center;
          align-items: center;
          flex-wrap: wrap;

          &.roundNone {
            display: none;
          }
        }

        .roundTwo {
          transition: 2s;
          opacity: 0;
          z-index: 0;

          &.activeRound {
            transition: 2s;
            width: 100%;
            position: unset !important;
            opacity: 1 !important;
          }

          .chooses {
            pointer-events: none;

            .choose {
              pointer-events: none;
            }
          }

          &.display {
            opacity: 1;
            pointer-events: auto;

            .chooses {
              pointer-events: auto;

              .choose {
                pointer-events: auto;
              }
            }
          }
        }
      }

      .nextContent {
        width: 100%;
        height: 100%;
        background-color: #000000;
        background-color: rgba(0, 0, 0, 0.47843);
        z-index: 100;
        display: none;
        position: absolute;
        top: 0;
        left: 0;
        -webkit-box-pack: center;
        -ms-flex-pack: center;
        justify-content: center;
        -webkit-box-align: center;
        -ms-flex-align: center;
        align-items: center;
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        z-index: 9999;

        .progress {
          display: -webkit-box;
          display: -ms-flexbox;
          display: flex;
          -webkit-box-pack: start;
          -ms-flex-pack: start;
          justify-content: start;
          -webkit-box-align: center;
          -ms-flex-align: center;
          align-items: center;
          -webkit-box-orient: vertical;
          -webkit-box-direction: normal;
          -ms-flex-direction: column;
          flex-direction: column;
          margin-top: 2vw;
          transform: scaleX(1);
          width: 100%;

          #progressbar {
            position: relative;
            width: 20vw;
            height: 3vw;
            display: flex;
            justify-content: center;
            align-items: center;
            margin-top: 3vw;
          }

          .finish {
            position: absolute;
            top: 4.5vw;
            z-index: 100;
            font-size: 2.3vw;
            left: 2.2vw;
            color: #22649c !important;
            font-weight: bold;
          }

          &.lower {
            margin-top: 0 !important;
          }
        }

        .character {
          width: 107vw;
          height: 35vw;
          position: relative;
          background-size: contain;
          background-position: center center;
          background-repeat: no-repeat;
          -webkit-animation: fade 0.3s linear;
          animation: fade 0.3s linear;
          display: flex;
          justify-content: center;
          align-items: flex-start;
          flex-direction: column;

          &.win {
            background-image: url(data:image/png;base64,);
          }

          &.lose {
            background-image: url(data:image/png;base64,);
          }

          .buttons {
            position: absolute;
            bottom: -2vw;
            width: 40%;
            height: 5vw;
            right: 0;
            left: 0;
            margin: 0 auto;
            display: -webkit-box;
            display: -ms-flexbox;
            display: flex;
            -ms-flex-pack: distribute;
            justify-content: space-around;
            -webkit-box-align: center;
            -ms-flex-align: center;
            align-items: center;

            button {
              width: 7vw;
              height: 7vw;
              border-radius: 50%;
              background-size: contain;
              background-position: center center;
              background-repeat: no-repeat;
              border: 0;
              background-color: transparent;

              &:focus {
                outline: none;
                opacity: 0.5;
              }

              &.home {
                background-image: url('data:image/png;base64,');
              }

              &.next {
                background-image: url('data:image/png;base64,');
              }
            }
          }

          .border {
            height: 80%;
            width: 100%;
            display: flex;
            justify-content: center;
            align-items: flex-start;

            .feedback-description {
              width: 40%;
              color: white;
              font-size: 2vw;
              font-weight: bold;

              direction: rtl;
              display: flex;
              justify-content: center;
              align-items: center;
              text-align: center;
            }
          }
        }
      }

      .progress #stars,
      .nextContent .progress .title {
        width: 16vw;
        color: white;
        height: 11vw;
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        position: absolute;
        top: -6vw;
        font-weight: bold;
        -webkit-box-align: center;
        -ms-flex-align: center;
        align-items: center;
        -webkit-box-pack: center;
        -ms-flex-pack: center;
        justify-content: center;
        background-size: contain;
        background-repeat: no-repeat;
        background-position: center center;
        padding-bottom: 2vw;
        background-image: url(data:image/png;base64,);

        p {
          span {
            font-size: 2.5vw;
          }
        }
      }

      .progress #stars {
        background-image: unset !important;
        width: 37% !important;
        height: 20vw !important;
        top: -11vw !important;
        left: 33%;
      }

      .box_score {
        display: flex;
        justify-content: space-evenly;
        align-items: center;
        background-image: url(data:image/png;base64,);
        width: 10vw;
        height: 4vw;
        padding: 0.5vw;
        background-size: 100% 100%;
        background-repeat: no-repeat;
        margin-top: 3vw;
        direction: rtl;

        p {
          color: white;
          font-size: 2vw;
          font-weight: bold;
          font-family: lexend-regular !important;
        }
      }

      .transition {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 0;
        overflow: hidden;
        display: flex;
        justify-content: center;
        align-items: center;
      }

      .transition.active {
        z-index: 1000;
      }

      .transition.active #rocket_final {
        pointer-events: auto;
        width: 100%;
        transform: scale(1.5);
        z-index: 10000;
      }

      .grade.lower {
        display: none;
      }

      .progress.eng {
        -webkit-transform: scaleX(-1);
        transform: scaleX(-1);

        .title {
          -webkit-transform: scaleX(-1);
          transform: scaleX(-1);
        }

        .box_score {
          -webkit-transform: scaleX(-1);
          transform: scaleX(-1);
          direction: rtl;
        }
      }

      .progress.lower .title,
      .progress #stars,
      .progress #progressbar {
        display: none;
      }

      .progress .title,
      #stars.active,
      #progressbar.active {
        display: block;
      }

      @-webkit-keyframes fade {
        from {
          opacity: 0;
        }

        to {
          opacity: 1;
        }
      }

      @keyframes fade {
        from {
          opacity: 0;
        }

        to {
          opacity: 1;
        }
      }

      @keyframes submit {
        from {
          bottom: -2vw;
          left: -4vw;
        }

        to {
          bottom: -1vw;
          left: -5vw;
        }
      }

      @keyframes displayAnswer {
        from {
          bottom: -2vw;
          left: 5vw;
        }

        to {
          bottom: -1vw;
          left: 6vw;
        }
      }

      @keyframes next {
        from {
          bottom: 3vw;
          left: -5vw;
        }

        to {
          bottom: 1vw;
          left: -3vw;
        }
      }

      @keyframes changeposition {
        0% {
          bottom: -3vw;
          left: 5vw;
        }

        100% {
          bottom: -4vw;
          left: 6vw;
        }
      }
    }

    .flex {
      display: flex;
      align-items: center;
    }

    .flexcloumn {
      display: flex;
      flex-direction: column;
    }

    .flexcenter {
      justify-content: center;
    }
  }
}

.table {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 115vh;
  height: 35vh;
  padding: 1vh;
  background-color: #cadadd82;
  border-radius: 2vw;

  .inner_table {
    width: 100%;
    height: 100%;
    border-radius: 2vw;
    border: solid 0.5vh #65858e;
    display: flex;
    background: white;

    .column_1,
    .column_2,
    .column_3,
    .column_4 {
      height: 100%;
      border-right: 0.4vh solid #65858e;

      .header_table,
      .center_table,
      .bottom_table {
        width: 100%;
        height: calc(100% / 3);
        display: flex;
        justify-content: center;
        align-items: center;
        border-bottom: 0.4vh solid #65858e;
      }

      .bottom_table {
        border-bottom: 0;
      }
    }

    .column_1 {
      width: 20%;

      .header_table {
        background-color: #f9aa8e;
        border-radius: 1.5vw 0 0 0.5vw;
      }

      .bottom_table {
        input {
          &.false,
          &.showAnswer,
          &.true {
            border-radius: 0 0 0 1.5vw !important;
          }
        }
      }
    }

    .column_2 {
      width: 10%;

      .header_table {
        background-color: #95dbad;
      }
    }

    .column_3 {
      width: 35%;

      .header_table {
        background-color: #fed7a0;
      }
    }

    .column_4 {
      width: 35%;
      border-right: 0;

      .header_table {
        background-color: #abe1fa;
        border-radius: 0 1.5vw 0.5vw 0;
      }

      .bottom_table {
        input {
          &.false,
          &.showAnswer,
          &.true {
            border-radius: 0 0 1.5vw 0 !important;
          }
        }
      }
    }
  }
}

.sign {
  width: 12vh;
  height: 9vh;
  margin: 0 3vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-size: 100% 100%;
  background-position: center;
  background-repeat: no-repeat;
  background-image: url(data:image/png;base64,);

  p {
    pointer-events: none;
    font-size: 7vw !important;
    // font-family: ArialRounded !important;
  }
}

.text-center {
  text-align: center;
  display: flex;
  justify-content: center;
  align-items: center;
}

.w60f {
  width: 60% !important;
}

.justify-end {
  justify-content: flex-end;
}
